INSERT INTO briefs (id, item_id, campaign_id, judul, versi, status, updated_by) VALUES (1, 49, 9, 'Brief @renovkm — Kamar Mandi Bersih November', 2, 'draft', 1);
INSERT INTO brief_sections (brief_id, urutan, judul, isi_json) VALUES (1, 1, 'Objective', '{"teks": "Mendorong kunjungan ke Mitra10 Pondok Bambu selama periode promo sanitary 10–24 Nov; target +900–1.500 kunjungan tambahan."}'::jsonb);
INSERT INTO brief_sections (brief_id, urutan, judul, isi_json) VALUES (1, 2, 'Pesan utama', '{"teks": "Renovasi kamar mandi tidak harus mahal: semua kebutuhan ada di Mitra10 Pondok Bambu, bisa dipasang sekalian."}'::jsonb);
INSERT INTO brief_sections (brief_id, urutan, judul, isi_json) VALUES (1, 3, 'Target audiens', '{"teks": "Keluarga muda 25–40 tahun di Jakarta Timur & Bekasi barat yang sedang/akan renovasi rumah."}'::jsonb);
INSERT INTO brief_sections (brief_id, urutan, judul, isi_json) VALUES (1, 4, 'Toko & promo', '{"teks": "Mitra10 Pondok Bambu — promo kloset duduk & keramik 30x30 diskon hingga 25%, cicilan 0%."}'::jsonb);
INSERT INTO brief_sections (brief_id, urutan, judul, isi_json) VALUES (1, 5, 'Storyboard per scene', '{"scene": [{"no": 1, "durasi": "0–3 dtk", "visual": "Kamar mandi lama, keramik retak", "audio": "Hook: ''Kamar mandi begini masih dipakai?''"}, {"no": 2, "durasi": "3–15 dtk", "visual": "Belanja di Mitra10 Pondok Bambu, pilih keramik & kloset", "audio": "Sebut promo & harga"}, {"no": 3, "durasi": "15–35 dtk", "visual": "Proses pasang (timelapse)", "audio": "Tips memilih keramik anti licin"}, {"no": 4, "durasi": "35–45 dtk", "visual": "Before–after", "audio": "CTA datang ke toko, sebut lokasi"}]}'::jsonb);
INSERT INTO brief_sections (brief_id, urutan, judul, isi_json) VALUES (1, 6, 'Wajib & dilarang', '{"wajib": "Sebut ''Mitra10 Pondok Bambu'', tampilkan papan promo, tag @mitra10official", "dilarang": "Menyebut merek kompetitor, klaim harga termurah tanpa syarat"}'::jsonb);
INSERT INTO brief_sections (brief_id, urutan, judul, isi_json) VALUES (1, 7, 'Caption & hashtag', '{"caption": "Renov kamar mandi 3 hari, budget aman! Semua belanja di @mitra10official Pondok Bambu 🔨", "hashtag": "#Mitra10 #RenovasiHemat #KamarMandiBersih"}'::jsonb);
INSERT INTO brief_sections (brief_id, urutan, judul, isi_json) VALUES (1, 8, 'Deliverable & timeline', '{"deliverable": "1 video TikTok 30–45 dtk + 2 story", "timeline": "Draft 7 Nov · Revisi maks 2× · Tayang 11 Nov 19.00 · Laporan H+3"}'::jsonb);
INSERT INTO brief_sections (brief_id, urutan, judul, isi_json) VALUES (1, 9, 'Referensi', '{"referensi": "Konten ''TT · Renov KM'' (612 rb views, Okt) — format tutorial < 45 dtk unggul 2,4×"}'::jsonb);
INSERT INTO uploads (id, jenis, nama_file, ringkasan_validasi_json, uploaded_by, uploaded_at) VALUES (1, 'traffic', 'traffic_harian_mei-nov_2026.xlsx', '{"baris_awal": 11041, "baris_siap": 11041, "toko": 61, "catatan": "data contoh"}'::jsonb, 1, '2026-11-04T07:00:00');
